import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Dx-TCpNt.js";const g=JSON.parse('{"title":"Terminology","description":"The three language versions of this manual use the terms below consistently. When a page and the UI disagree, the UI label wins; when in doubt, consult…","frontmatter":{"description":"The three language versions of this manual use the terms below consistently. When a page and the UI disagree, the UI label wins; when in doubt, consult…"},"headers":[],"relativePath":"terminology.md","filePath":"terminology.md","lastUpdated":1794778371000}'),o={name:"terminology.md"};function n(i,t,s,l,h,p){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;Terminology&quot;">​</a></h1><p>The three language versions of this manual use the terms below consistently. When a page and the UI disagree, the UI label wins; when in doubt, consult the table.</p><p>This is the shared dictionary for translators and for readers hopping between languages — yes, the panel / 分格 / コマ situation is real, and it is intentional.</p><p>UI labels are quoted in the interface language, so a button may read differently from the prose. This table is the shared reference for translators and for readers switching languages.</p><h2 id="core-objects" tabindex="-1">Core objects <a class="header-anchor" href="#core-objects" aria-label="Permalink to &quot;Core objects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>English</th><th>中文</th><th>日本語</th></tr></thead><tbody><tr><td>A box on a page</td><td>panel</td><td>分格</td><td>コマ</td></tr><tr><td>The artwork panels are drawn on</td><td>base image</td><td>底图</td><td>下地画像</td></tr><tr><td>An image file on disk</td><td>page</td><td>页面</td><td>ページ</td></tr><tr><td>A folder of pages</td><td>chapter</td><td>话</td><td>話</td></tr><tr><td>A top-level folder</td><td>volume</td><td>卷</td><td>巻</td></tr><tr><td>The whole scanned collection</td><td>library</td><td>图库</td><td>ライブラリ</td></tr><tr><td>Two pages printed as one image</td><td>spread</td><td>跨页</td><td>見開き</td></tr></tbody></table><h2 id="panels-and-alignment" tabindex="-1">Panels and alignment <a class="header-anchor" href="#panels-and-alignment" aria-label="Permalink to &quot;Panels and alignment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>English</th><th>中文</th><th>日本語</th></tr></thead><tbody><tr><td>Automatic panel detection</td><td>auto split</td><td>自动切格</td><td>自動分割</td></tr><tr><td>Combining panels into one</td><td>merge</td><td>合并</td><td>結合</td></tr><tr><td>Panel numbering</td><td>reading order</td><td>阅读顺序</td><td>読み順</td></tr><tr><td>Horizontal or vertical reading</td><td>reading direction</td><td>阅读方向</td><td>読み方向</td></tr><tr><td>Making two editions overlap</td><td>alignment</td><td>对齐</td><td>位置合わせ</td></tr><tr><td>A per-language displacement</td><td>offset</td><td>偏移</td><td>オフセット</td></tr><tr><td>A reference point for alignment</td><td>anchor</td><td>锚点</td><td>アンカー</td></tr><tr><td>Snapping to a fixed step</td><td>grid snap</td><td>网格吸附</td><td>グリッド吸着</td></tr><tr><td>A saved alignment</td><td>preset</td><td>预设</td><td>プリセット</td></tr><tr><td>A saved set of rectangles</td><td>panel template</td><td>分格模板</td><td>コマテンプレート</td></tr><tr><td>A declarative page grid</td><td>layout template</td><td>布局模板</td><td>レイアウトテンプレート</td></tr><tr><td>Several panels read as one unit</td><td>group</td><td>分组</td><td>グループ</td></tr></tbody></table><h2 id="preparation-rules-and-history" tabindex="-1">Preparation, rules and history <a class="header-anchor" href="#preparation-rules-and-history" aria-label="Permalink to &quot;Preparation, rules and history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>English</th><th>中文</th><th>日本語</th></tr></thead><tbody><tr><td>Cleaning up scans before import</td><td>preparation / preprocessing</td><td>预处理</td><td>前処理</td></tr><tr><td>Renaming a whole folder at once</td><td>batch rename</td><td>批量重命名</td><td>一括リネーム</td></tr><tr><td>A path pattern for the scanner</td><td>folder rule / directory rule</td><td>目录识别规则</td><td>フォルダ検出規則</td></tr><tr><td>A part of a path pattern</td><td>segment</td><td>路径段</td><td>パスセグメント</td></tr><tr><td>A segment that may be absent</td><td>optional segment</td><td>可选段</td><td>省略可能セグメント</td></tr><tr><td>A one-segment placeholder</td><td>wildcard</td><td>通配符</td><td>ワイルドカード</td></tr><tr><td>A saved state of a page</td><td>version / page history</td><td>版本 / 页面历史</td><td>バージョン / ページ履歴</td></tr><tr><td>One entry in the history</td><td>snapshot</td><td>快照</td><td>スナップショット</td></tr><tr><td>Producing a PDF from the browser</td><td>print to PDF</td><td>打印为 PDF</td><td>PDF として印刷</td></tr></tbody></table><h2 id="reading-and-annotation" tabindex="-1">Reading and annotation <a class="header-anchor" href="#reading-and-annotation" aria-label="Permalink to &quot;Reading and annotation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>English</th><th>中文</th><th>日本語</th></tr></thead><tbody><tr><td>Hiding artwork for self-testing</td><td>mask</td><td>遮蔽</td><td>マスク</td></tr><tr><td>A blur or solid cover</td><td>mask style</td><td>遮蔽样式</td><td>マスクスタイル</td></tr><tr><td>Drawing on the artwork</td><td>annotation</td><td>标注</td><td>注釈</td></tr><tr><td>A vector mark</td><td>arrow / rectangle / ellipse</td><td>箭头 / 矩形 / 椭圆</td><td>矢印 / 矩形 / 楕円</td></tr><tr><td>Pixelating an area</td><td>mosaic</td><td>马赛克</td><td>モザイク</td></tr><tr><td>Writing about a page or panel</td><td>note</td><td>笔记</td><td>ノート</td></tr><tr><td>The note column</td><td>notes panel</td><td>笔记栏</td><td>ノート欄</td></tr><tr><td>A label on a note</td><td>tag</td><td>标签</td><td>タグ</td></tr><tr><td>Where a note came from</td><td>source</td><td>来源</td><td>出典</td></tr><tr><td>Draft notes area</td><td>scratchpad</td><td>暂存区</td><td>スクラッチパッド</td></tr></tbody></table><h2 id="storage-and-export" tabindex="-1">Storage and export <a class="header-anchor" href="#storage-and-export" aria-label="Permalink to &quot;Storage and export&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>English</th><th>中文</th><th>日本語</th></tr></thead><tbody><tr><td>The generated document</td><td>HTML export</td><td>HTML 导出</td><td>HTML エクスポート</td></tr><tr><td>A Word document export</td><td>Word document</td><td>Word 文档</td><td>Word 文書</td></tr><tr><td>A static image export</td><td>PNG export</td><td>PNG 导出</td><td>PNG エクスポート</td></tr><tr><td>The browser print view used for PDF</td><td>print view</td><td>打印视图</td><td>印刷ビュー</td></tr><tr><td>A reusable document style</td><td>export template</td><td>导出模板</td><td>エクスポートテンプレート</td></tr><tr><td>A portable project archive</td><td>project package</td><td>工程包</td><td>プロジェクトパッケージ</td></tr><tr><td>A single layout or page file</td><td>exchange file</td><td>交换文件</td><td>交換ファイル</td></tr><tr><td>A full data archive</td><td>backup</td><td>备份</td><td>バックアップ</td></tr><tr><td>Where a backup is uploaded</td><td>backup target</td><td>备份目标</td><td>バックアップ先</td></tr><tr><td>A remote image source</td><td>remote assets</td><td>远端素材</td><td>リモート素材</td></tr><tr><td>Fetching an image when opened</td><td>on-demand fetch</td><td>按需拉取</td><td>オンデマンド取得</td></tr><tr><td>Local copy of a remote original</td><td>cache</td><td>缓存</td><td>キャッシュ</td></tr><tr><td>A zero-byte mirror entry</td><td>placeholder</td><td>占位文件</td><td>プレースホルダー</td></tr><tr><td>A reduced preview image</td><td>thumbnail</td><td>缩略图</td><td>サムネイル</td></tr><tr><td>The file format version</td><td>schema version</td><td>格式版本</td><td>スキーマバージョン</td></tr></tbody></table><h2 id="words-we-avoid" tabindex="-1">Words we avoid <a class="header-anchor" href="#words-we-avoid" aria-label="Permalink to &quot;Words we avoid&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Avoid</th><th>Use instead</th><th>Why</th></tr></thead><tbody><tr><td>image / picture (for a scanned page)</td><td>page</td><td>“Image” is ambiguous with exported PNGs.</td></tr><tr><td>crop box</td><td>panel</td><td>A crop is an export operation; the stored rectangle is a panel.</td></tr><tr><td>translation</td><td>compare</td><td>The app compares editions; it does not translate.</td></tr><tr><td>sync (for annotations)</td><td>save</td><td>Annotations are local; nothing is uploaded.</td></tr><tr><td>template (alone)</td><td>panel template / layout template / export template</td><td>Three different objects share the word.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/concepts">Core Concepts</a> — the data model in prose.</li><li><a href="/KomaYomi-docs/data-format">Data Formats</a> — field names and versions.</li><li><a href="/KomaYomi-docs/guide/shortcuts">Keyboard Shortcuts</a> — the keys that drive these objects.</li></ul>',18)])])}const m=d(o,[["render",n]]);export{g as __pageData,m as default};
